    df_dq[2] += coefficients[start_idx + 5] * 1.0 * q_pows[1, 1]

    # Coefficient 6: Exponents (0, 1, 2)
    length += coefficients[start_idx + 6] * q_pows[1, 1] * q_pows[2, 2]
    df_dq[1] += coefficients[start_idx + 6] * 1.0 * q_pows[2, 2]
    df_dq[2] += coefficients[start_idx + 6] * 2.0 * q_pows[1, 1] * q_pows[2, 1]

