    length += coefficients[start_idx + 11] * q_pows[0, 1] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 11] * 1.0 * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 11] * 1.0 * q_pows[0, 1]

