    df_dq[2] += coefficients[start_idx + 27] * 2.0 * q_pows[0, 2] * q_pows[2, 1]

    # Coefficient 28: Exponents (2, 1, 0)
    length += coefficients[start_idx + 28] * q_pows[0, 2] * q_pows[1, 1]
