    # Coefficient 29: Exponents (2, 1, 1)
    length += coefficients[start_idx + 29] * q_pows[0, 2] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 29] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 29] * 1.0 * q_pows[0, 2] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 29] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 30: Exponents (2, 2, 0)
    length += coefficients[start_idx + 30] * q_pows[0, 2] * q_pows[1, 2]
