    df_dq[2] += coefficients[start_idx + 43] * 2.0 * q_pows[0, 1] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 43] * 1.0 * q_pows[0, 1] * q_pows[2, 2]

    # Coefficient 44: Exponents (1, 0, 3, 0)
    length += coefficients[start_idx + 44] * q_pows[0, 1] * q_pows[2, 3]
