    df_dq[3] += coefficients[start_idx + 46] * 1.0 * q_pows[0, 1] * q_pows[1, 1]

    # Coefficient 47: Exponents (1, 1, 0, 2)
    length += coefficients[start_idx + 47] * q_pows[0, 1] * q_pows[1, 1] * q_pows[3, 2]
    df_dq[0] += coefficients[start_idx + 47] * 1.0 * q_pows[1, 1] * q_pows[3, 2]
    df_dq[1] += coefficients[start_idx + 47] * 1.0 * q_pows[0, 1] * q_pows[3, 2]
    df_dq[3] += coefficients[start_idx + 47] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[3, 1]

    # Coefficient 48: Exponents (1, 1, 1, 0)
    length += coefficients[start_idx + 48] * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 48] * 1.0 * q_pows[1, 1] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 48] * 1.0 * q_pows[0, 1] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 48] * 1.0 * q_pows[0, 1] * q_pows[1, 1]

    # Coefficient 49: Exponents (1, 1, 1, 1)
    length += coefficients[start_idx + 49] * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[0] += coefficients[start_idx + 49] * 1.0 * q_pows[1, 1] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[1] += coefficients[start_idx + 49] * 1.0 * q_pows[0, 1] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[2] += coefficients[start_idx + 49] * 1.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 49] * 1.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]

    # Coefficient 50: Exponents (1, 1, 2, 0)
    length += coefficients[start_idx + 50] * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 2]
    df_dq[0] += coefficients[start_idx + 50] * 1.0 * q_pows[1, 1] * q_pows[2, 2]
    df_dq[1] += coefficients[start_idx + 50] * 1.0 * q_pows[0, 1] * q_pows[2, 2]
    df_dq[2] += coefficients[start_idx + 50] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]

    # Coefficient 51: Exponents (1, 2, 0, 0)
    length += coefficients[start_idx + 51] * q_pows[0, 1] * q_pows[1, 2]
    df_dq[0] += coefficients[start_idx + 51] * 1.0 * q_pows[1, 2]
    df_dq[1] += coefficients[start_idx + 51] * 2.0 * q_pows[0, 1] * q_pows[1, 1]

    # Coefficient 52: Exponents (1, 2, 0, 1)
    length += coefficients[start_idx + 52] * q_pows[0, 1] * q_pows[1, 2] * q_pows[3, 1]
