    df_dq[1] += coefficients[start_idx + 53] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 53] * 1.0 * q_pows[0, 1] * q_pows[1, 2]

