    df_dq[2] += coefficients[start_idx + 175] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]

    # Coefficient 176: Exponents (1, 2, 0, 0, 0, 0)
    length += coefficients[start_idx + 176] * q_pows[0, 1] * q_pows[1, 2]
    df_dq[0] += coefficients[start_idx + 176] * 1.0 * q_pows[1, 2]
    df_dq[1] += coefficients[start_idx + 176] * 2.0 * q_pows[0, 1] * q_pows[1, 1]

    # Coefficient 177: Exponents (1, 2, 0, 0, 0, 1)
    length += coefficients[start_idx + 177] * q_pows[0, 1] * q_pows[1, 2] * q_pows[5, 1]
