    df_dq[5] += coefficients[start_idx + 177] * 1.0 * q_pows[0, 1] * q_pows[1, 2]

    # Coefficient 178: Exponents (1, 2, 0, 0, 1, 0)
    length += coefficients[start_idx + 178] * q_pows[0, 1] * q_pows[1, 2] * q_pows[4, 1]
