    df_dq[4] += coefficients[start_idx + 178] * 1.0 * q_pows[0, 1] * q_pows[1, 2]

    # Coefficient 179: Exponents (1, 2, 0, 1, 0, 0)
    length += coefficients[start_idx + 179] * q_pows[0, 1] * q_pows[1, 2] * q_pows[3, 1]
