    df_dq[1] += coefficients[start_idx + 179] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 179] * 1.0 * q_pows[0, 1] * q_pows[1, 2]

    # Coefficient 180: Exponents (1, 2, 1, 0, 0, 0)
    length += coefficients[start_idx + 180] * q_pows[0, 1] * q_pows[1, 2] * q_pows[2, 1]
