    df_dq[1] += coefficients[start_idx + 292] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 292] * 1.0 * q_pows[0, 1] * q_pows[1, 2]

    # Coefficient 293: Exponents (1, 3, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 293] * q_pows[0, 1] * q_pows[1, 3]
    df_dq[0] += coefficients[start_idx + 293] * 1.0 * q_pows[1, 3]
    df_dq[1] += coefficients[start_idx + 293] * 3.0 * q_pows[0, 1] * q_pows[1, 2]

    # Coefficient 294: Exponents (2, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 294] * q_pows[0, 2]
    df_dq[0] += coefficients[start_idx + 294] * 2.0 * q_pows[0, 1]

    # Coefficient 295: Exponents (2, 0, 0, 0, 0, 0, 1)
    length += coefficients[start_idx + 295] * q_pows[0, 2] * q_pows[6, 1]
