    df_dq[6] += coefficients[start_idx + 295] * 1.0 * q_pows[0, 2]

    # Coefficient 296: Exponents (2, 0, 0, 0, 0, 0, 2)
    length += coefficients[start_idx + 296] * q_pows[0, 2] * q_pows[6, 2]
