    df_dq[6] += coefficients[start_idx + 296] * 2.0 * q_pows[0, 2] * q_pows[6, 1]

    # Coefficient 297: Exponents (2, 0, 0, 0, 0, 1, 0)
    length += coefficients[start_idx + 297] * q_pows[0, 2] * q_pows[5, 1]
