    df_dq[5] += coefficients[start_idx + 297] * 1.0 * q_pows[0, 2]

    # Coefficient 298: Exponents (2, 0, 0, 0, 0, 1, 1)
    length += coefficients[start_idx + 298] * q_pows[0, 2] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[0] += coefficients[start_idx + 298] * 2.0 * q_pows[0, 1] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[5] += coefficients[start_idx + 298] * 1.0 * q_pows[0, 2] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 298] * 1.0 * q_pows[0, 2] * q_pows[5, 1]

    # Coefficient 299: Exponents (2, 0, 0, 0, 0, 2, 0)
    length += coefficients[start_idx + 299] * q_pows[0, 2] * q_pows[5, 2]
