    df_dq[5] += coefficients[start_idx + 299] * 2.0 * q_pows[0, 2] * q_pows[5, 1]

    # Coefficient 300: Exponents (2, 0, 0, 0, 1, 0, 0)
    length += coefficients[start_idx + 300] * q_pows[0, 2] * q_pows[4, 1]
