    df_dq[4] += coefficients[start_idx + 300] * 1.0 * q_pows[0, 2]

    # Coefficient 301: Exponents (2, 0, 0, 0, 1, 0, 1)
    length += coefficients[start_idx + 301] * q_pows[0, 2] * q_pows[4, 1] * q_pows[6, 1]
