    df_dq[4] += coefficients[start_idx + 301] * 1.0 * q_pows[0, 2] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 301] * 1.0 * q_pows[0, 2] * q_pows[4, 1]

    # Coefficient 302: Exponents (2, 0, 0, 0, 1, 1, 0)
    length += coefficients[start_idx + 302] * q_pows[0, 2] * q_pows[4, 1] * q_pows[5, 1]
