    length += coefficients[start_idx + 491] * q_pows[0, 3] * q_pows[3, 1]
    df_dq[0] += coefficients[start_idx + 491] * 3.0 * q_pows[0, 2] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 491] * 1.0 * q_pows[0, 3]

