    df_dq[4] += coefficients[start_idx + 986] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 987: Exponents (2, 1, 0, 1, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 987] * q_pows[0, 2] * q_pows[1, 1] * q_pows[3, 1]
    df_dq[0] += coefficients[start_idx + 987] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[3, 1]
