    df_dq[2] += coefficients[start_idx + 988] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 989: Exponents (2, 2, 0, 0, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 989] * q_pows[0, 2] * q_pows[1, 2]
