    df_dq[7] += coefficients[start_idx + 993] * 1.0 * q_pows[0, 3]

    # Coefficient 994: Exponents (3, 0, 0, 0, 0, 0, 1, 0, 0, 0)
    length += coefficients[start_idx + 994] * q_pows[0, 3] * q_pows[6, 1]
    df_dq[0] += coefficients[start_idx + 994] * 3.0 * q_pows[0, 2] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 994] * 1.0 * q_pows[0, 3]

    # Coefficient 995: Exponents (3, 0, 0, 0, 0, 1, 0, 0, 0, 0)
    length += coefficients[start_idx + 995] * q_pows[0, 3] * q_pows[5, 1]
