    df_dq[3] += coefficients[start_idx + 997] * 1.0 * q_pows[0, 3]

    # Coefficient 998: Exponents (3, 0, 1, 0, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 998] * q_pows[0, 3] * q_pows[2, 1]
