    # Coefficient 32: Exponents (0, 0, 0, 0, 0, 0, 0, 0, 0, 3, 0, 1)
    length += coefficients[start_idx + 32] * q_pows[9, 3] * q_pows[11, 1]
    df_dq[9] += coefficients[start_idx + 32] * 3.0 * q_pows[9, 2] * q_pows[11, 1]
    df_dq[11] += coefficients[start_idx + 32] * 1.0 * q_pows[9, 3]

    # Coefficient 33: Exponents (0, 0, 0, 0, 0, 0, 0, 0, 0, 3, 1, 0)
    length += coefficients[start_idx + 33] * q_pows[9, 3] * q_pows[10, 1]
    df_dq[9] += coefficients[start_idx + 33] * 3.0 * q_pows[9, 2] * q_pows[10, 1]
